import os,sys,time,json
sys.path.insert(0,'/opt/tools')
import numpy as np, mujoco, rcb_dtb
from scipy.spatial.transform import Rotation as Rot
from PIL import Image

class Controller:
 def __init__(self):
  self.s=rcb_dtb.Session('/app/instance.json');self.m=self.s.model;self.d=self.s.data
  self.k=mujoco.MjData(self.m);self.bid=self.m.body('palmleft_hand_C_MC').id
  self.jp=np.zeros((3,self.m.nv));self.jr=self.jp.copy()
 def pose(self):return self.d.xpos[self.bid].copy(),self.d.xmat[self.bid].reshape(3,3).copy()
 def obj(self):return self.d.xpos[self.s._obj].copy(),self.d.xmat[self.s._obj].reshape(3,3).copy()
 def ik(self,p,R,q=None):
  if q is None:q=self.s.targets[:7].copy()
  self.k.qpos[:]=self.d.qpos
  for it in range(80):
   self.k.qpos[self.s._jq[:7]]=q;mujoco.mj_kinematics(self.m,self.k);mujoco.mj_comPos(self.m,self.k)
   e=np.r_[p-self.k.xpos[self.bid],Rot.from_matrix(R@self.k.xmat[self.bid].reshape(3,3).T).as_rotvec()]
   if np.linalg.norm(e)<1e-6:break
   mujoco.mj_jacBody(self.m,self.k,self.jp,self.jr,self.bid)
   J=np.r_[self.jp[:,:7],self.jr[:,:7]]
   dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*.0001,e)
   q=np.clip(q+np.clip(dq,-.15,.15),self.s.lower[:7]+.005,self.s.upper[:7]-.005)
  return q
 def move(self,p,R,hand=None,n=120):
  q=self.ik(p,R);a=self.s.targets.copy();b=a.copy();b[:7]=q
  if hand is not None:b[7:]=hand
  for t in range(n):
   u=(t+1)/n;u=u*u*(3-2*u);self.s.step(a+(b-a)*u)
  return self.s.progress()
 def hold(self,n=60):
  for _ in range(n):self.s.step(self.s.targets)
 def snap(self,name):
  Image.fromarray(self.s.render_grid(size=(640,480))).save('/app/output/'+name+'.png')
 def info(self):
  print('step',self.s.steps,'progress',self.s.progress(),'object',self.obj()[0],'H',self.pose()[0],flush=True)
  contacts=[]
  for con in self.d.contact:
   b1,b2=self.m.geom_bodyid[[con.geom1,con.geom2]]
   if self.s._obj in [b1,b2]:contacts.append((self.m.geom(con.geom1).name,self.m.geom(con.geom2).name,round(con.dist,4)))
  print('contacts',contacts,flush=True)

def grasp(c, x=.035,z=.125,close=None):
 s=c.s;c.hold(30);op,OR=c.obj()
 hx=np.array([0,0,-1.]);hy=-OR[:,0];hy[2]=0;hy/=np.linalg.norm(hy);hz=np.cross(hx,hy);R=np.c_[hx,hy,hz]
 p=op-R@np.array([x,0,z])
 c.move(p+np.array([0,0,.10]),R,n=150)
 c.move(p,R,n=150);c.snap('pre');c.info()
 if close is None:close=np.array([1.4,.15,.6,0,1.0]+[.8,0,1.2,1.0]*3+[0,.8,0,1.2,1.0])
 c.move(p,R,close,n=120);c.hold(60);c.snap('closed');c.info()
 c.move(p+np.array([0,0,.13]),R,n=180);c.hold(60);c.snap('lift');c.info()
 return R

if __name__=='__main__':
 c=Controller();c.s.record_start();grasp(c);A=c.s.record_stop();c.s.save_trajectory(A,'/app/output/test.npz')
PY
